{
  "name": "@suiramdev/opencode-with-claude",
  "description": "OpenCode v2 plugin to use your Claude Max/Pro subscription via the Meridian proxy",
  "version": "2.0.0",
  "type": "module",
  "main": "dist/index.js",
  "types": "dist/index.d.ts",
  "dependencies": {
    "@rynfar/meridian": "^1.60.0",
    "@rynfar/meridian-plugin-opencode-scrub": "^0.2.0"
  },
  "devDependencies": {
    "@opencode-ai/plugin": "0.0.0-next-16741",
    "@types/node": "^26.1.1",
    "tsup": "^8.5.1",
    "typescript": "^7.0.2"
  },
  "scripts": {
    "build": "tsup && tsc",
    "test": "./test/run.sh",
    "test:unit": "npm run build && node --experimental-strip-types --test test/unit/*.test.mjs",
    "test:clean": "./test/run.sh --clean",
    "prepublishOnly": "npm run build"
  },
  "files": [
    "dist"
  ],
  "publishConfig": {
    "access": "public"
  },
  "repository": {
    "type": "git",
    "url": "git+https://github.com/ianjwhite99/opencode-with-claude.git"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "claude",
    "claude-max",
    "proxy"
  ],
  "license": "MIT"
}
